corrected_code:
namespace App\Livewire;

use Livewire\Component;
use App\Models\Tenant;
use App\Services\StripeSubscriptionService;
use Illuminate\Support\Facades\Auth;

class ChangeSubscriptionTier extends Component
{
    public int $tenantId;
    public string $newPlanTier = 'starter';

    public function changeTier(StripeSubscriptionService $stripe)
    {
        $tenant = Auth::user()->tenants()->findOrFail($this->tenantId);
        $this->authorize('manageBilling', $tenant);

        $stripe->updateSubscriptionTier($tenant, $this->newPlanTier);
    }

    public function render()
    {
        return view('livewire.change-subscription-tier');
    }
}
